// Let's write a solver to find optimal balanced teams
const players = [
  { name: "Cody", hcp: 1 },
  { name: "C", hcp: 3 },
  { name: "Greg", hcp: 4 },
  { name: "Johnny", hcp: 4 },
  { name: "Dave", hcp: 4 },
  { name: "Sal", hcp: 4 },
  { name: "Lane", hcp: 5 },
  { name: "Steve", hcp: 10 },
  { name: "Christian", hcp: 11 },
  { name: "Carl", hcp: 11 },
  { name: "Rawley", hcp: 11 },
  { name: "Gary", hcp: 13 },
  { name: "Albert", hcp: 14 },
  { name: "Eric", hcp: 16 },
  { name: "Doric", hcp: 17 },
  { name: "Marcus", hcp: 18 }
];

// Let's verify sum
const totalSum = players.reduce((a, b) => a + b.hcp, 0);
console.log("Total handicap sum:", totalSum, "Target per team:", totalSum / 4);

// Function to calculate USGA 4-person scramble handicap:
// 25% of lowest, 20% of 2nd lowest, 15% of 3rd lowest, 10% of highest
function calcScrambleHcp(team) {
  const sorted = [...team].sort((a, b) => a.hcp - b.hcp);
  return 0.25 * sorted[0].hcp + 0.20 * sorted[1].hcp + 0.15 * sorted[2].hcp + 0.10 * sorted[3].hcp;
}

// Let's divide into 4 balanced tiers:
// Tier 1 (A players): Cody (1), C (3), Greg (4), Johnny (4)
// Tier 2 (B players): Dave (4), Sal (4), Lane (5), Steve (10)
// Tier 3 (C players): Christian (11), Carl (11), Rawley (11), Gary (13)
// Tier 4 (D players): Albert (14), Eric (16), Doric (17), Marcus (18)

// Notice every team gets exactly one A player, one B player, one C player, one D player!
// Let's find all permutations of matching A, B, C, D to minimize difference in total handicap and scramble handicap.

const tierA = [players[0], players[1], players[2], players[3]]; // Cody (1), C (3), Greg (4), Johnny (4)
const tierB = [players[4], players[5], players[6], players[7]]; // Dave (4), Sal (4), Lane (5), Steve (10)
const tierC = [players[8], players[9], players[10], players[11]]; // Christian (11), Carl (11), Rawley (11), Gary (13)
const tierD = [players[12], players[13], players[14], players[15]]; // Albert (14), Eric (16), Doric (17), Marcus (18)

console.log("Tier counts:", tierA.length, tierB.length, tierC.length, tierD.length);

function getPermutations(arr) {
  if (arr.length <= 1) return [arr];
  const perms = [];
  for (let i = 0; i < arr.length; i++) {
    const rest = [...arr.slice(0, i), ...arr.slice(i + 1)];
    for (const p of getPermutations(rest)) {
      perms.push([arr[i], ...p]);
    }
  }
  return perms;
}

const permsB = getPermutations(tierB);
const permsC = getPermutations(tierC);
const permsD = getPermutations(tierD);

let bestCombinations = [];

for (const b of permsB) {
  for (const c of permsC) {
    for (const d of permsD) {
      const teams = [
        [tierA[0], b[0], c[0], d[0]],
        [tierA[1], b[1], c[1], d[1]],
        [tierA[2], b[2], c[2], d[2]],
        [tierA[3], b[3], c[3], d[3]]
      ];

      const totals = teams.map(t => t.reduce((s, p) => s + p.hcp, 0));
      const spreads = teams.map(t => Math.max(...t.map(p => p.hcp)) - Math.min(...t.map(p => p.hcp)));
      const scrambles = teams.map(t => calcScrambleHcp(t));

      const maxTotDiff = Math.max(...totals) - Math.min(...totals);
      const maxScrambleDiff = Math.max(...scrambles) - Math.min(...scrambles);

      // We want minimal maxTotDiff (ideal is 1, since 146/4 = 36.5, so two 36s and two 37s)
      if (maxTotDiff <= 1) {
        bestCombinations.push({
          teams,
          totals,
          spreads,
          scrambles,
          maxTotDiff,
          maxScrambleDiff
        });
      }
    }
  }
}

console.log("Number of balanced combinations with max total diff <= 1:", bestCombinations.length);

// Sort by minimal maxScrambleDiff
bestCombinations.sort((a, b) => a.maxScrambleDiff - b.maxScrambleDiff);

for (let i = 0; i < Math.min(3, bestCombinations.length); i++) {
  console.log(`\n--- Candidate Option ${i + 1} (Max Tot Diff: ${bestCombinations[i].maxTotDiff}, Max Scramble Diff: ${bestCombinations[i].maxScrambleDiff.toFixed(3)}) ---`);
  bestCombinations[i].teams.forEach((t, idx) => {
    const names = t.map(p => `${p.name} (${p.hcp})`).join(", ");
    const total = bestCombinations[i].totals[idx];
    const avg = (total / 4).toFixed(2);
    const spread = bestCombinations[i].spreads[idx];
    const scr = bestCombinations[i].scrambles[idx].toFixed(2);
    const scrRounded = Math.round(bestCombinations[i].scrambles[idx]);
    console.log(`Team ${idx + 1}: ${names} | Total: ${total} | Avg: ${avg} | Spread: ${spread} | USGA Scramble Hcp: ${scr} (Playing Hcp: ${scrRounded})`);
  });
}

