// Let's test and open the 5 courses in separate tabs

const courses = [
  { name: "Sleepy Hollow Golf Course", url: "https://www.clevelandmetroparks.com/golf/courses/sleepy-hollow-golf-course" },
  { name: "Manakiki Golf Course", url: "https://www.clevelandmetroparks.com/golf/courses/manakiki-golf-course" },
  { name: "Boulder Creek Golf Club", url: "https://www.bouldercreekohio.com/" },
  { name: "Pine Hills Golf Club", url: "https://www.golfpinehills.net/" },
  { name: "Fowler's Mill Golf Course", url: "https://www.fowlersmillgc.com/" }
];

const results = [];

for (const c of courses) {
  try {
    const tabRes = await tool.tabs_create({ url: c.url });
    const tabId = tabRes.details?.tabId;
    console.log(`Created tab for ${c.name}: ${tabId}`);
    await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 }).catch(e => console.log(`Wait load timeout/err on ${c.name}:`, e.message));

    // Quick inspection of page title / content
    const info = await browserjs(tabId, () => ({
      title: document.title,
      textLength: document.body.innerText.length,
      snippet: document.body.innerText.slice(0, 300).replace(/\s+/g, ' ')
    })).catch(e => ({ error: e.message }));

    results.push({ name: c.name, tabId, url: c.url, info });
  } catch (err) {
    console.error(`Error opening ${c.name}:`, err.message);
  }
}

console.log("Course tab results:", JSON.stringify(results, null, 2));

