// Let's find the bounding rect of the iframe or editor container
const rect = await browserjs(cpTabId, () => {
  const iframe = document.getElementById('sbox-iframe');
  if (!iframe) return null;
  const innerDoc = iframe.contentDocument || iframe.contentWindow?.document;
  if (!innerDoc) return { crossOrigin: true };
  const editorIframe = innerDoc.querySelector('iframe');
  return {
    crossOrigin: false,
    editorIframe: editorIframe ? editorIframe.getBoundingClientRect() : null
  };
});
console.log("Rect info:", rect);

