args.code:
const cpTabId = 1675924512;

// Let's test pasting rich text via clipboard or inserting text
const testContent = `# 16-PLAYER GOLF OUTING GUIDE & SETUP`;

// Let's click in the editor area to focus
await tool.mouse({
  action: "left_click",
  tabId: cpTabId,
  coordinate: [500, 350]
});

// Select all
await tool.press({ tabId: cpTabId, keys: "ControlOrMeta+a" });

// Let's write text to clipboard and paste
await browserjs(cpTabId, async (text) => {
  try {
    await navigator.clipboard.writeText(text);
    return { ok: true };
  } catch (e) {
    return { error: e.message };
  }
}, testContent);

const pasteRes = await tool.press({ tabId: cpTabId, keys: "ControlOrMeta+v" });
console.log("Paste result:", pasteRes);

await tool.wait_for({ tabId: cpTabId, condition: "dom_settled", timeout_ms: 2000 }).catch(() => {});

// Let's check if the status is "Saved" or "Editing"
const snap = await browser.snapshot({ tabId: cpTabId });
const statusLine = snap.text.split('\n').find(l => l.includes('Saved') || l.includes('Editing') || l.includes('Saving'));
console.log("CryptPad status:", statusLine);

